using System;using System.IO;using System.Diagnostics;using System.Collections.Generic;using System.Reflection;using System.Web.Script.Serialization;
public class UpdateFile {public string Path,Hash;}
public class UpdateTicket {public string Target,Stage,Version;public int Parent;public long ParentStart;public UpdateFile[] Files;}
public static class SelfUpdate {
 static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=4000000};}
 public static string NewWorkspace(){string root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"LegacySteamFixer/Updates/"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);return root;}
 static bool Allowed(string path){string top=path.Split('/')[0].ToLowerInvariant();if(path.Contains("/"))return top=="inject"||top=="zstd"||top=="probes"||top=="modules"||top=="templates";return path=="LegacySteamFixer.exe"||path=="LegacySteamFixer.exe.config"||path.EndsWith(".txt",StringComparison.OrdinalIgnoreCase)||path.EndsWith(".md",StringComparison.OrdinalIgnoreCase);}
 public static UpdateTicket Stage(string package,string workspace,string target,string version){
  if(UpdateService.Compare(version,AppInfo.Version)<=0)throw new Exception("Update must be newer than this Fixer");
  string unpack=Path.Combine(workspace,"unpack");SafeZip.Extract(package,unpack);string root=unpack;
  if(!File.Exists(Path.Combine(root,"LegacySteamFixer.exe"))){var dirs=Directory.GetDirectories(root);if(dirs.Length!=1||Directory.GetFiles(root).Length!=0)throw new Exception("Runtime package root not found");root=dirs[0];}
  foreach(string dir in Directory.GetDirectories(root,"*",SearchOption.AllDirectories)){string rel=dir.Substring(root.Length+1).Replace(Path.DirectorySeparatorChar,'/');if(!Allowed(rel+"/"))throw new Exception("Update contains a non-runtime directory: "+rel);}
  var files=new List<UpdateFile>();foreach(string f in Directory.GetFiles(root,"*",SearchOption.AllDirectories)){string rel=f.Substring(root.Length+1).Replace(Path.DirectorySeparatorChar,'/');if(!Allowed(rel)||rel.Equals("zstd/OldSteam_VSZa_Launcher.exe",StringComparison.OrdinalIgnoreCase))throw new Exception("Unexpected update file: "+rel);files.Add(new UpdateFile{Path=rel,Hash=Core.Hash(f)});}
  foreach(string required in new[]{"LegacySteamFixer.exe","LegacySteamFixer.exe.config","modules/catalog.json","inject/LegacySteam-Injector.exe","inject/LegacySteam-InjectBridge.dll","templates/bridge-x64.dll","zstd/LegacySteam-ZstdModule.dll","zstd/steam_zstd.dll","zstd/vsza_hook.bin"})if(!File.Exists(Core.Inside(root,required)))throw new Exception("Incomplete runtime package: "+required);
  var name=AssemblyName.GetAssemblyName(Path.Combine(root,"LegacySteamFixer.exe"));string expected=version.TrimStart('v');var info=FileVersionInfo.GetVersionInfo(Path.Combine(root,"LegacySteamFixer.exe"));if(name.Name!="LegacySteamFixer"||info.ProductVersion!=expected)throw new Exception("Update executable version mismatch");
  return new UpdateTicket{Target=Path.GetFullPath(target),Stage=root,Version=version,Files=files.ToArray()};
 }
 public static void Start(UpdateTicket ticket){using(var parent=Process.GetCurrentProcess()){ticket.Parent=parent.Id;ticket.ParentStart=parent.StartTime.ToUniversalTime().Ticks;}
  string work=Path.GetDirectoryName(ticket.Stage);string helper=Path.Combine(work,"LegacySteamFixer.exe");File.Copy(Path.Combine(Core.Base,"LegacySteamFixer.exe"),helper,false);File.Copy(Path.Combine(Core.Base,"LegacySteamFixer.exe.config"),helper+".config",false);string request=Path.Combine(work,"update.json");File.WriteAllText(request,Json().Serialize(ticket));
  using(var p=Process.Start(new ProcessStartInfo(helper,"--apply-update "+ZstdSupport.Quote(request)){UseShellExecute=false,WorkingDirectory=work})){if(p==null)throw new Exception("Could not start update worker");}
 }
 static void CheckRoot(string target){for(string d=Path.GetFullPath(target);!string.IsNullOrEmpty(d);d=Path.GetDirectoryName(d))if(Directory.Exists(d)&&(File.GetAttributes(d)&FileAttributes.ReparsePoint)!=0)throw new Exception("Update folder is a reparse point");}
 public static void Apply(UpdateTicket t,string backup,Action<string> beforeWrite){
  CheckRoot(t.Target);var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var f in t.Files){SafeZip.ValidateName(f.Path);if(!Allowed(f.Path)||!seen.Add(f.Path))throw new Exception("Invalid update file list");if(Core.Hash(Core.Inside(t.Stage,f.Path))!=f.Hash)throw new Exception("Staged update changed: "+f.Path);Core.Inside(t.Target,f.Path);}
  var paths=new List<string>();foreach(var f in t.Files)paths.Add(f.Path);paths.Add("zstd/OldSteam_VSZa_Launcher.exe");Directory.CreateDirectory(backup);var existing=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
  foreach(string rel in paths){string old=Core.Inside(t.Target,rel);if(File.Exists(old)){string save=Core.Inside(backup,rel);Directory.CreateDirectory(Path.GetDirectoryName(save));File.Copy(old,save,false);existing.Add(rel);}}
  // Recovery metadata survives an interrupted process.
  File.WriteAllText(Path.Combine(backup,"recovery.json"),Json().Serialize(new{Target=t.Target,Files=paths,Existing=existing}));
  var changed=new List<string>();try{foreach(var f in t.Files){if(beforeWrite!=null)beforeWrite(f.Path);changed.Add(f.Path);Replace(Core.Inside(t.Stage,f.Path),Core.Inside(t.Target,f.Path));if(Core.Hash(Core.Inside(t.Target,f.Path))!=f.Hash)throw new Exception("Installed update verification failed: "+f.Path);}
   string obsolete="zstd/OldSteam_VSZa_Launcher.exe";if(File.Exists(Core.Inside(t.Target,obsolete))){changed.Add(obsolete);File.Delete(Core.Inside(t.Target,obsolete));}
  }catch(Exception failure){var errors=new List<string>();for(int i=changed.Count-1;i>=0;i--){string rel=changed[i];try{string dest=Core.Inside(t.Target,rel);if(existing.Contains(rel))Replace(Core.Inside(backup,rel),dest);else if(File.Exists(dest))File.Delete(dest);}catch(Exception e){errors.Add(rel+": "+e.Message);}}if(errors.Count>0)throw new Exception(failure.Message+"\nRollback incomplete. Recovery files: "+backup+"\n"+string.Join("\n",errors.ToArray()));throw new Exception(failure.Message+"\nOriginal version restored. Recovery files: "+backup);}
 }
 static void Replace(string source,string dest){Directory.CreateDirectory(Path.GetDirectoryName(dest));string temp=dest+".update-"+Guid.NewGuid().ToString("N");try{File.Copy(source,temp,false);if(File.Exists(dest))File.Replace(temp,dest,null);else File.Move(temp,dest);}finally{if(File.Exists(temp))File.Delete(temp);}}
 public static int Worker(string request){UpdateTicket ticket=null;string work=Path.GetDirectoryName(request);try{ticket=Json().Deserialize<UpdateTicket>(File.ReadAllText(request));if(ticket==null||ticket.Files==null)throw new Exception("Invalid update request");
   Process parent=null;try{parent=Process.GetProcessById(ticket.Parent);}catch(ArgumentException){}if(parent!=null)using(parent){if(parent.StartTime.ToUniversalTime().Ticks!=ticket.ParentStart||!parent.MainModule.FileName.Equals(Path.Combine(ticket.Target,"LegacySteamFixer.exe"),StringComparison.OrdinalIgnoreCase))throw new Exception("Update parent does not match");if(!parent.WaitForExit(60000))throw new Exception("Fixer has not exited; no update applied");}
   foreach(var process in Process.GetProcessesByName("LegacySteamFixer"))using(process){if(process.Id==Process.GetCurrentProcess().Id)continue;string path;try{path=process.MainModule.FileName;}catch(InvalidOperationException){continue;}if(path.Equals(Path.Combine(ticket.Target,"LegacySteamFixer.exe"),StringComparison.OrdinalIgnoreCase))throw new Exception("Close other Fixer windows before updating");}
   Apply(ticket,Path.Combine(work,"backup"),null);File.WriteAllText(Path.Combine(work,"success.txt"),ticket.Version);Process.Start(new ProcessStartInfo(Path.Combine(ticket.Target,"LegacySteamFixer.exe")){UseShellExecute=true,WorkingDirectory=ticket.Target});return 0;
  }catch(Exception e){string text="更新未完成 / Update did not complete\n\n"+e.Message+"\n\n"+work;try{File.WriteAllText(Path.Combine(work,"error.txt"),text);}catch{}System.Windows.Forms.MessageBox.Show(text,"LegacySteamFixer",System.Windows.Forms.MessageBoxButtons.OK,System.Windows.Forms.MessageBoxIcon.Error);return 1;}}
}
